// Parser Food.com-felterne i R-format c("a", "b") og normaliserer data
const parseR = s => {
  if (!s || s === 'NA' || s === 'character(0)') return [];
  return [...String(s).matchAll(/"([^"]*)"/g)].map(m => m[1].trim()).filter(Boolean);
};
// ISO-varighed (PT1H30M) -> minutter
const toMin = iso => {
  const m = String(iso || '').match(/PT(?:(\d+)H)?(?:(\d+)M)?/);
  return m ? Number(m[1] || 0) * 60 + Number(m[2] || 0) : null;
};
return $input.all().map(({ json: r }) => {
  const ingredients = [...new Set(parseR(r.RecipeIngredientParts).map(i => i.toLowerCase()))];
  const tags = [...new Set(parseR(r.Keywords).map(t => t.toLowerCase()))];
  const steps = parseR(r.RecipeInstructions);
  const id = String(parseInt(r.RecipeId));
  const category = r.RecipeCategory || 'Other';
  return { json: {
    id,
    name: r.Name,
    totalTime: toMin(r.TotalTime),
    calories: Number(r.Calories) || null,
    rating: Number(r.AggregatedRating) || null,
    servings: Number(r.RecipeServings) || null,
    category,
    authorId: String(parseInt(r.AuthorId) || 'unknown'),
    authorName: r.AuthorName || null,
    ingredients,
    tags,
    chunkText: [
      r.Name + '.',
      r.Description || '',
      'Category: ' + category,
      'Tags: ' + tags.join(', '),
      'Ingredients: ' + ingredients.join(', '),
      'Instructions: ' + steps.join(' ')
    ].join(' | ')
  }};
});

// Samler alle opskrifter i én Cypher-statement til grafen
const recipes = $input.all().map(({ json }) => {
  const { chunkText, ...rest } = json;
  return rest;
});
const statement = [
  'UNWIND $recipes AS r',
  'MERGE (rec:Recipe {id: r.id})',
  'SET rec.name = r.name, rec.totalTime = r.totalTime, rec.calories = r.calories, rec.rating = r.rating, rec.servings = r.servings',
  'MERGE (c:Category {name: r.category})',
  'MERGE (rec)-[:IN_CATEGORY]->(c)',
  'MERGE (a:Author {id: r.authorId})',
  'SET a.name = r.authorName',
  'MERGE (rec)-[:AUTHORED_BY]->(a)',
  'FOREACH (i IN r.ingredients | MERGE (ing:Ingredient {name: i}) MERGE (rec)-[:HAS_INGREDIENT]->(ing))',
  'FOREACH (t IN r.tags | MERGE (tag:Tag {name: t}) MERGE (rec)-[:HAS_TAG]->(tag))'
].join(' ');
return [{ json: { statements: [{ statement, parameters: { recipes } }] } }];

// Kobler hver embedding sammen med sin opskrift og bygger Cypher til chunks
const recipes = $('Parse opskrifter').all();
const chunks = $input.all().map((item, i) => ({
  id: recipes[i].json.id + '-main',
  recipeId: recipes[i].json.id,
  text: recipes[i].json.chunkText,
  embedding: item.json.embeddings[0],
  source: 'Food.com recipes.csv (RecipeId ' + recipes[i].json.id + ')',
  type: 'recipe'
}));
const statement = [
  'UNWIND $chunks AS ch',
  'MERGE (r:Recipe {id: ch.recipeId})',
  'MERGE (c:Chunk {id: ch.id})',
  'SET c.text = ch.text, c.embedding = ch.embedding, c.source = ch.source, c.type = ch.type',
  'MERGE (c)-[:PART_OF]->(r)'
].join(' ');
return [{ json: { statements: [{ statement, parameters: { chunks } }] } }];
